import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AdminService } from '../../../core/services/admin.service';
import { User } from '../../../core/models';

@Component({
  selector: 'app-users',
  templateUrl: './users.component.html'
})
export class UsersComponent implements OnInit {

  users: User[] = [];
  form: FormGroup;
  loading = false;
  success = '';
  error = '';

  constructor(private fb: FormBuilder, private adminService: AdminService) {
    this.form = this.fb.group({
      name:     ['', [Validators.required, Validators.minLength(2)]],
      email:    ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],
      role:     ['RECEPTIONIST', Validators.required]
    });
  }

  ngOnInit(): void { this.load(); }

  load(): void {
    this.adminService.getUsers().subscribe(u => this.users = u);
  }

  submit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    this.success = '';

    this.adminService.createUser(this.form.value).subscribe({
      next: () => {
        this.success = 'User created successfully.';
        this.form.reset({ role: 'RECEPTIONIST' });
        this.load();
        this.loading = false;
      },
      error: err => {
        this.error = err.error?.message ?? 'Failed to create user.';
        this.loading = false;
      }
    });
  }

  toggleStatus(user: User): void {
    const action = user.active
      ? this.adminService.deactivateUser(user.id)
      : this.adminService.activateUser(user.id);
    action.subscribe(() => this.load());
  }
}
<div class="page-header">
  <h2>Staff Users</h2>
  <p>Create Admin and Receptionist accounts</p>
</div>

<div class="card" style="max-width:480px;">
  <h4 style="margin-bottom:16px;">Add Staff User</h4>
  <div *ngIf="success" class="alert alert-success">{{ success }}</div>
  <div *ngIf="error"   class="alert alert-danger">{{ error }}</div>

  <form [formGroup]="form" (ngSubmit)="submit()">
    <div class="form-group">
      <label>Full Name *</label>
      <input formControlName="name" placeholder="Staff Name">
    </div>
    <div class="form-group">
      <label>Email *</label>
      <input type="email" formControlName="email" placeholder="staff@hospital.com">
    </div>
    <div class="form-group">
      <label>Password *</label>
      <input type="password" formControlName="password" placeholder="Min 6 characters">
    </div>
    <div class="form-group">
      <label>Role *</label>
      <select formControlName="role">
        <option value="ADMIN">Admin</option>
        <option value="RECEPTIONIST">Receptionist</option>
      </select>
    </div>
    <button class="btn btn-primary" [disabled]="loading">
      {{ loading ? 'Creating...' : 'Create User' }}
    </button>
  </form>
</div>

<div class="card">
  <h4 style="margin-bottom:16px;">All Staff ({{ users.length }})</h4>
  <table>
    <thead>
      <tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr>
    </thead>
    <tbody>
      <tr *ngFor="let u of users">
        <td>{{ u.name }}</td>
        <td>{{ u.email }}</td>
        <td><span class="badge badge-normal">{{ u.role }}</span></td>
        <td>
          <span class="badge"
            [class.badge-completed]="u.active"
            [class.badge-waiting]="!u.active">
            {{ u.active ? 'Active' : 'Inactive' }}
          </span>
        </td>
        <td>
          <button class="btn"
            [class.btn-danger]="u.active"
            [class.btn-success]="!u.active"
            (click)="toggleStatus(u)"
            style="font-size:12px;padding:4px 10px;">
            {{ u.active ? 'Deactivate' : 'Activate' }}
          </button>
        </td>
      </tr>
    </tbody>
  </table>
</div>
